create extension if not exists pgcrypto;
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),full_name text not null check(length(trim(full_name)) between 1 and 160),business_name text,whatsapp_number text,email text,business_category text not null default 'Other',location text,services_of_interest text[] not null default '{}',status text not null default 'New' check(status in('New','Active','Returning','Inactive','Archived')),internal_notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.inquiries(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id) on delete set null,customer_name text not null check(length(trim(customer_name)) between 1 and 160),business_name text,whatsapp_number text not null,email text,requested_service text not null,customer_budget text,project_description text not null,preferred_deadline text,source text not null default 'Website' check(source in('Website','WhatsApp','Email','Instagram','Facebook','Referral','Other')),status text not null default 'New' check(status in('New','Contacted','Interested','Quotation Sent','Awaiting Decision','Awaiting Payment','Converted','Lost')),internal_notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete restrict,inquiry_id uuid references public.inquiries(id) on delete set null,project_name text not null check(length(trim(project_name)) between 1 and 200),service_type text not null,description text not null default '',agreed_price numeric(12,2) not null default 0 check(agreed_price>=0),start_date date,deadline date,status text not null default 'Awaiting Payment' check(status in('Awaiting Payment','Ready to Start','In Progress','Awaiting Client Feedback','Revisions Required','Completed','Cancelled')),delivery_link text,internal_notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete restrict,project_id uuid not null references public.projects(id) on delete restrict,amount numeric(12,2) not null check(amount>0),currency text not null default 'GHS' check(currency='GHS'),payment_method text not null default 'Other' check(payment_method in('Mobile Money','Bank Transfer','Cash','Other')),payment_date timestamptz not null default now(),payment_reference text,notes text not null default '',status text not null default 'Recorded' check(status in('Recorded','Voided')),void_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.follow_ups(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id) on delete cascade,inquiry_id uuid references public.inquiries(id) on delete cascade,reason text not null,scheduled_date timestamptz not null,status text not null default 'Pending' check(status in('Pending','Completed','Cancelled')),notes text not null default '',completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(client_id is not null or inquiry_id is not null));
create table if not exists public.activity_logs(id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid,action text not null,description text not null,created_at timestamptz not null default now());
create index if not exists clients_name_idx on public.clients using gin(to_tsvector('simple',coalesce(full_name,'')||' '||coalesce(business_name,'')||' '||coalesce(whatsapp_number,'')||' '||coalesce(email,'')));
create index if not exists inquiries_status_created_idx on public.inquiries(status,created_at desc);
create index if not exists inquiries_client_idx on public.inquiries(client_id);
create index if not exists projects_client_status_idx on public.projects(client_id,status);
create index if not exists projects_deadline_idx on public.projects(deadline);
create index if not exists payments_project_date_idx on public.payments(project_id,payment_date desc);
create index if not exists payments_client_date_idx on public.payments(client_id,payment_date desc);
create index if not exists followups_schedule_status_idx on public.follow_ups(status,scheduled_date);
create index if not exists followups_client_idx on public.follow_ups(client_id);
create index if not exists activity_created_idx on public.activity_logs(created_at desc);
create or replace function public.crm_touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text;begin foreach t in array array['clients','inquiries','projects','payments','follow_ups'] loop execute format('drop trigger if exists %I_touch_updated_at on public.%I',t,t);execute format('create trigger %I_touch_updated_at before update on public.%I for each row execute function public.crm_touch_updated_at()',t,t);end loop;end $$;
create or replace function public.crm_project_paid(p_project_id uuid) returns numeric language sql stable security definer set search_path=public as $$ select coalesce(sum(amount),0) from public.payments where project_id=p_project_id and status='Recorded' $$;
create or replace function public.crm_project_balance(p_project_id uuid) returns numeric language sql stable security definer set search_path=public as $$ select greatest(0,p.agreed_price-public.crm_project_paid(p.id)) from public.projects p where p.id=p_project_id $$;
alter table public.clients enable row level security;alter table public.inquiries enable row level security;alter table public.projects enable row level security;alter table public.payments enable row level security;alter table public.follow_ups enable row level security;alter table public.activity_logs enable row level security;
do $$ declare t text;begin foreach t in array array['clients','inquiries','projects','payments','follow_ups','activity_logs'] loop execute format('drop policy if exists "crm owner access" on public.%I',t);execute format('create policy "crm owner access" on public.%I for all to authenticated using ((auth.jwt()->>''email'')=''radacliffemensah@gmail.com'') with check ((auth.jwt()->>''email'')=''radacliffemensah@gmail.com'')',t);end loop;end $$;
drop policy if exists "public can submit inquiries" on public.inquiries;
create policy "public can submit inquiries" on public.inquiries for insert to anon,authenticated with check(status='New' and source='Website' and client_id is null and length(trim(customer_name)) between 1 and 160 and length(trim(whatsapp_number)) between 7 and 30 and length(trim(requested_service)) between 1 and 120 and length(trim(project_description)) between 1 and 5000);
grant select,insert,update,delete on public.clients,public.inquiries,public.projects,public.payments,public.follow_ups,public.activity_logs to authenticated;grant insert on public.inquiries to anon;